namespace Retune.Mpv.Tests.Support;

/// <summary>Locates the synthetic media generated by tools/make-test-media.ps1.</summary>
internal static class TestMedia
{
    public const string Vod1080p = "vod-1080p.mp4";
    public const string Live720p = "live-720p.ts";
    public const string NoAudio = "no-audio.mp4";
    public const string MultiTrack = "multi-track.mkv";

    private static readonly Lazy<string> Folder = new(FindFolder);

    public static string PathOf(string name)
    {
        var path = System.IO.Path.Combine(Folder.Value, name);
        return File.Exists(path)
            ? path
            : throw new FileNotFoundException($"Test media '{name}' is missing. Run tools\\make-test-media.ps1 first.", path);
    }

    private static string FindFolder()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
        {
            if (File.Exists(System.IO.Path.Combine(dir.FullName, "global.json")))
            {
                return System.IO.Path.Combine(dir.FullName, "tests", "fixtures", "media");
            }
        }

        throw new DirectoryNotFoundException("Repository root (global.json) not found above the test output folder.");
    }
}
